CREATE TABLE sections (id SERIAL PRIMARY KEY, slug TEXT NOT NULL UNIQUE, label TEXT NOT NULL, icon TEXT NOT NULL DEFAULT 'FolderOpen', color TEXT NOT NULL DEFAULT 'from-violet-500 to-purple-600', sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE TABLE materials (id SERIAL PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', tag TEXT NOT NULL DEFAULT '', color TEXT NOT NULL DEFAULT 'from-violet-500 to-purple-600', icon TEXT NOT NULL DEFAULT 'BookOpen', section_slug TEXT NOT NULL REFERENCES sections(slug), created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE TABLE notifications (id SERIAL PRIMARY KEY, text TEXT NOT NULL, type TEXT NOT NULL DEFAULT 'task', created_at TIMESTAMPTZ NOT NULL DEFAULT now());